package home

import (
	"context"
	"errors"
	"fmt"
	"html/template"
	"io"
	"log"
	"net/http"
	"net/url"
	"regexp"
	"strings"
	"time"

	"garrison/control-plane/internal/events"
)

// The Units page shows each unit's unit.md (docs/ontology.md): what it is
// now, generated by the gateway as the person may see it. /u lists the
// person's own units, /u/<unit> one, /u/<unit>.md the same as Markdown.

// UnitPages gives unit.md, as a person may see it: the gateway's.
type UnitPages interface {
	UnitMD(ctx context.Context, unit, person string) (string, error)
	PersonUnitsMD(ctx context.Context, person string) (string, error)
}

// ErrUnitHidden: the person cannot see the unit.
var ErrUnitHidden = errors.New("unit hidden")

type unitsView struct {
	Unit string        // one unit's page; "" for the person's units
	Body template.HTML // unit.md, rendered
	Raw  string        // the link to the Markdown
	Err  string
}

func (s *Server) unitsPage(w http.ResponseWriter, r *http.Request, v events.Visibility) {
	unit := r.PathValue("unit")
	if strings.HasSuffix(unit, ".md") {
		s.unitMarkdown(w, r, v, strings.TrimSuffix(unit, ".md"))
		return
	}
	view := &unitsView{Unit: unit}
	var md string
	var err error
	if unit == "" {
		md, err = s.Units.PersonUnitsMD(r.Context(), v.Person)
	} else {
		view.Raw = "/u/" + url.PathEscape(unit) + ".md"
		md, err = s.Units.UnitMD(r.Context(), unit, v.Person)
	}
	switch {
	case errors.Is(err, ErrUnitHidden):
		http.NotFound(w, r)
		return
	case err != nil:
		log.Printf("home: unit.md %q for %s: %v", unit, v.Person, err)
		view.Err = "It cannot be read right now: " + err.Error()
	default:
		view.Body = renderMD(md)
	}
	s.render(w, "page", feedPage{Who: v.Person, Domain: s.Domain, All: v.All, Now: s.now(), UnitsPage: view})
}

func (s *Server) unitMarkdown(w http.ResponseWriter, r *http.Request, v events.Visibility, unit string) {
	md, err := s.Units.UnitMD(r.Context(), unit, v.Person)
	switch {
	case errors.Is(err, ErrUnitHidden):
		http.NotFound(w, r)
	case err != nil:
		http.Error(w, err.Error(), http.StatusServiceUnavailable)
	default:
		w.Header().Set("Content-Type", "text/markdown; charset=utf-8")
		io.WriteString(w, md)
	}
}

var (
	mdLink = regexp.MustCompile(`https?://[^\s<>"')]+[^\s<>"').,;:]`)
	mdCode = regexp.MustCompile("`([^`]+)`")
	mdAt   = regexp.MustCompile(`(^|[\s(])@([a-z][a-z0-9-]*)`)
)

// renderMD is the HTML of unit.md's few forms: headings, lists, paragraphs,
// addresses as links, `code`, and @agents as agents; everything escaped.
func renderMD(md string) template.HTML {
	var b strings.Builder
	inList := false
	closeList := func() {
		if inList {
			b.WriteString("</ul>\n")
			inList = false
		}
	}
	inline := func(s string) string {
		s = template.HTMLEscapeString(s)
		s = mdCode.ReplaceAllString(s, "<code>$1</code>")
		s = mdLink.ReplaceAllStringFunc(s, func(u string) string {
			return `<a href="` + u + `">` + u + `</a>`
		})
		s = mdAt.ReplaceAllStringFunc(s, func(m string) string {
			g := mdAt.FindStringSubmatch(m)
			return g[1] + string(agentTag(g[2]))
		})
		return s
	}
	for _, line := range strings.Split(md, "\n") {
		t := strings.TrimSpace(line)
		switch {
		case t == "":
			closeList()
		case strings.HasPrefix(t, "## "):
			closeList()
			b.WriteString("<h2>" + inline(t[3:]) + "</h2>\n")
		case strings.HasPrefix(t, "# "):
			closeList()
			b.WriteString("<h1>" + inline(t[2:]) + "</h1>\n")
		case strings.HasPrefix(t, "- "):
			if !inList {
				b.WriteString("<ul class=\"unitlist\">\n")
				inList = true
			}
			b.WriteString("<li>" + inline(t[2:]) + "</li>\n")
		default:
			closeList()
			b.WriteString("<p>" + inline(t) + "</p>\n")
		}
	}
	closeList()
	return template.HTML(b.String()) // every text escaped above
}

// RemoteUnits asks the gateway for unit.md, with the service key.
func RemoteUnits(gatewayURL, serviceKey string) UnitPages {
	return remoteUnits{url: strings.TrimSuffix(gatewayURL, "/"), key: serviceKey, http: &http.Client{Timeout: 30 * time.Second}}
}

type remoteUnits struct {
	url, key string
	http     *http.Client
}

func (u remoteUnits) get(ctx context.Context, path string) (string, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.url+path, nil)
	if err != nil {
		return "", err
	}
	req.Header.Set("X-Garrison-Service", u.key)
	resp, err := u.http.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	data, _ := io.ReadAll(io.LimitReader(resp.Body, 256<<10))
	switch resp.StatusCode {
	case http.StatusOK:
		return string(data), nil
	case http.StatusForbidden, http.StatusBadRequest:
		return "", ErrUnitHidden
	}
	return "", fmt.Errorf("%s: %s", resp.Status, strings.TrimSpace(string(data)))
}

func (u remoteUnits) UnitMD(ctx context.Context, unit, person string) (string, error) {
	return u.get(ctx, "/internal/units/"+url.PathEscape(unit)+"/unit.md?for="+url.QueryEscape(person))
}

func (u remoteUnits) PersonUnitsMD(ctx context.Context, person string) (string, error) {
	return u.get(ctx, "/internal/people/"+url.PathEscape(person)+"/units.md")
}
